mapper.sql:
WHERE user_apps.is_active = 3

    AND (
    user_apps.first_name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR user_apps.last_name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR user_apps.username LIKE CONCAT('%', #{filter.searchText}, '%')
    OR user_apps.telephone LIKE CONCAT('%', #{filter.searchText}, '%')
    OR user_apps.email LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND user_apps.dob >= #{filter.dobFrom}


    AND user_apps.dob <= #{filter.dobTo}

mapper.select:
SELECT user_apps.id AS id, TRIM(CONCAT(IFNULL(user_apps.first_name, ''), ' ', IFNULL(user_apps.last_name, ''))) AS name, user_apps.telephone AS phoneNumber, user_apps.email AS email, user_apps.sex AS gender, DATE_FORMAT(user_apps.dob, '%Y-%m-%d') AS dob, DATE_FORMAT(user_apps.created, '%Y-%m-%d') AS created, user_apps.address AS address FROM user_apps
ORDER BY user_apps.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}
